"""Build a local review page from real checkpoint IDs; never submits a task."""
from pathlib import Path
import sys,json
sys.path.insert(0,str(Path(__file__).parent))
from setup import ROOT,OUT,write,sha

def run():
    pilot=json.loads((OUT/'pilot.json').read_text(encoding='utf-8'))
    labels={'a-face':'01 · 林安面部','a-body':'02 · 林安全身与轻微转身','b-action':'03 · 周言简单动作','ab-frame':'04 · 两人同框'}
    manifest=dict(projectId=pilot['projectId'],episodeId=pilot['episodeId'],actors=pilot['actors'],slots=[dict(key=k,label=labels[k],**v) for k,v in pilot['slots'].items()],preview=pilot.get('preview'),contentReview='NeedReview',publication='Blocked')
    payload=json.dumps(manifest,ensure_ascii=False).replace('<','\\u003c')
    html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>人物剧情试片 · 本地审核</title>
<style>:root{color-scheme:dark;font-family:system-ui,"Microsoft YaHei",sans-serif;background:#0c1320;color:#e8edf6}*{box-sizing:border-box}body{margin:0}main{max-width:1440px;padding:36px 28px 70px;margin:auto}a{color:#92d8d1;text-decoration:none}nav{display:flex;gap:22px;flex-wrap:wrap}h1{font-size:34px;letter-spacing:.03em;margin:28px 0 14px}h2{font-size:23px;margin:0 0 15px}h3{font-size:17px;margin:12px 0}p{line-height:1.75;color:#b6c3d6}small{color:#9daec4;line-height:1.8}.banner{border:1px solid #78623c;background:#302a1e;padding:16px 20px;border-radius:12px;color:#f3dca9;margin:24px 0}.hero,.card{border:1px solid #26374e;background:#131e2e;border-radius:16px;padding:24px;margin-top:24px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{min-width:0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:14px}.badge{display:inline-block;border-radius:20px;padding:5px 12px;background:#27384d;color:#d9e8f5;font-size:13px}.Passed{background:#183d37;color:#9de8d7}.Failed{background:#512b31;color:#ffd1d6}video,img{width:100%;aspect-ratio:16/9;object-fit:contain;background:#080d15;border-radius:9px}img{cursor:zoom-in}video{max-height:70vh}.status{white-space:pre-wrap;line-height:1.7;color:#c7d0e0;font-size:14px}.status.error{color:#ffa6b0}details{border-top:1px solid #2a3a50;padding-top:14px;margin-top:18px}summary{cursor:pointer;color:#b6d2e8}details pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;color:#a6b8cc}.history{display:grid;gap:14px;margin-top:16px}button{border:1px solid #466579;background:#203749;color:#e1edf6;border-radius:7px;padding:8px 14px;cursor:pointer}.meta{font-size:13px;overflow-wrap:anywhere}.preview{max-width:1000px;margin:auto}dialog{border:1px solid #3c516a;border-radius:12px;background:#0a101c;color:white;width:min(96vw,1700px);max-height:96vh}dialog::backdrop{background:#000c}dialog img{width:100%;max-height:84vh;aspect-ratio:auto}footer{margin-top:30px;color:#7e91ac;font-size:13px}@media(max-width:900px){.grid{grid-template-columns:1fr}.pair{grid-template-columns:1fr}main{padding:22px 15px}h1{font-size:27px}}</style>
<main><nav><a href="/#character-story">← 剧情选角与试片</a><a href="/#character-library">人物参考库</a><a href="/character-reference-pack.html">九图参考包</a><button id="refresh">刷新实际任务</button></nav>
<h1>人物参考 → 剧情关键帧 → 视频试片</h1><p>阅读室 · 林安与周言。固定人物及造型版本，逐镜头检查和定向修复。</p>
<div class="banner"><strong>送审预览 · 人工内容待审 · 发布资格 Blocked</strong><br>技术完成与试片检查分别记录。此页默认静音；本集选择后期配音，合成预览去除 H3 原声，避免重复人声。</div>
<section class="hero"><h2>四镜头合成预览</h2><div id="preview" class="preview"></div></section><div id="grid" class="grid"></div>
<footer>人物参考库保存人物设定、参考图和不可变造型版本；不表示已训练专属模型或三维人物。双人画面需逐张复核，H3 多参考 Ref2VA 未启用。来源与失败历史均可展开查看。</footer></main>
<dialog id="zoom"><button id="closeZoom">关闭原图</button><img alt="剧情与参考原图放大"></dialog><script>
const data=__PAYLOAD__;
const media=p=>'/api/media?assetPath='+encodeURIComponent(p);
const el=(tag,text,cls)=>{const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x};
const get=async p=>{const r=await fetch(p);if(!r.ok)throw Error('读取失败 '+r.status);return r.json()};
function image(path,alt){const x=el('img');x.src=media(path);x.alt=alt;x.loading='lazy';x.onclick=()=>{document.querySelector('#zoom img').src=x.src;document.querySelector('#zoom').showModal()};return x}
function player(path,label){const v=el('video');v.src=media(path);v.controls=true;v.muted=true;v.preload='metadata';v.setAttribute('aria-label',label);return v}
async function output(entry,kind,label,parent,review){if(!entry?.id){parent.append(el('p','尚未提交'));return}const detail=await get('/api/tasks/'+entry.id);parent.append(el('small','任务 #'+entry.id+' · '+detail.task.status));const asset=detail.results.find(r=>r.available&&r.assetPath?.endsWith(kind==='Keyframe'?'.png':'.mp4'));if(asset)parent.append(kind==='Keyframe'?image(asset.assetPath,label):player(asset.assetPath,label));else parent.append(el('p','实际任务仍在执行或没有可用输出'));if(review)parent.append(el('p',review.payload.decision+' / '+review.payload.scope+'：'+review.payload.note,'status'+(review.payload.decision==='Failed'?' error':'')));return detail}
async function load(){document.querySelector('#grid').replaceChildren();for(const s of data.slots){const card=el('section',undefined,'card');card.append(el('h2',s.label));document.querySelector('#grid').append(card);try{const shot=await get('/api/character-story/shots/'+s.shotId),plan=shot.plans.find(p=>p.id===s.planId);const getReview=id=>shot.tasks.find(t=>t.id===id)?.review;const review=getReview(s.Video?.id),badge=el('span',review?.payload.decision||'待检查','badge '+(review?.payload.decision||''));card.append(badge,el('p','镜头 #'+s.shotId+' · '+(plan?.payload.actors.map(a=>a.role+' / 人物版本 #'+a.versionId).join('；')||''),'meta'));const pair=el('div',undefined,'pair'),staticSide=el('div'),videoSide=el('div');staticSide.append(el('h3','剧情关键帧'));videoSide.append(el('h3','H3 视频'));pair.append(staticSide,videoSide);card.append(pair);await output(s.Keyframe,'Keyframe',s.label+' 关键帧',staticSide);await output(s.Video,'Video',s.label+' 视频',videoSide,review);const source=el('details'),summary=el('summary','来源参考、生成参数与检查记录');source.append(summary);for(const a of plan?.payload.actors||[]){source.append(el('h3',a.role+' · 固定人物与造型'),image(a.identity.assetPath,a.role+' 身份参考'),image(a.outfitReference.assetPath,a.role+' 造型参考'))}source.append(el('pre',JSON.stringify({plan,selectedTasks:shot.tasks.filter(t=>[s.Keyframe?.id,s.Video?.id].includes(t.id))},null,2)));card.append(source);const old=[...(s.KeyframeHistory||[]).map(t=>[t,'Keyframe']),...(s.VideoHistory||[]).map(t=>[t,'Video'])];if(old.length){const history=el('details'),list=el('div',undefined,'history');history.append(el('summary','查看保留的失败素材与定向修复历史（'+old.length+'项）'),list);for(const [t,kind] of old){const entry=el('div');entry.append(el('h3',kind+' · 原任务 #'+t.id));await output(t,kind,s.label+' 原失败素材',entry,getReview(t.id));list.append(entry)}card.append(history)}}catch(e){card.append(el('p',e.message,'status error'))}}
const p=document.querySelector('#preview');p.replaceChildren();if(data.preview?.id){try{await output(data.preview,'Video','四镜头合成预览',p);p.append(el('p','后期配音预览：无原生音轨。人物、动作与跨镜头连续性仍需人工最终审核。'))}catch(e){p.append(el('p',e.message,'status error'))}}else p.append(el('p','各镜头完成试片检查后再合成。失败镜头保留原结果，修复通过前不会混入交付预览。'));}
document.querySelector('#refresh').onclick=load;document.querySelector('#closeZoom').onclick=()=>document.querySelector('#zoom').close();load();
</script></html>'''.replace('__PAYLOAD__',payload)
    for folder in [ROOT/'web/public',ROOT/'web/dist']:
        folder.mkdir(parents=True,exist_ok=True);(folder/'character-story-preview.html').write_text(html,encoding='utf-8')
    write(OUT/'preview-page.json',dict(url='http://127.0.0.1:18080/character-story-preview.html',pageSha256=sha(ROOT/'web/public/character-story-preview.html'),manifest=manifest,realTaskReadsOnly=True))
    print('Local review page built from registered real task IDs; no GPU submission or content approval.')
if __name__=='__main__':run()
